import{_ as a,o as r,c as t,a7 as s}from"./chunks/framework.BJyR0VjM.js";const g=JSON.parse('{"title":"Console Forwarding","description":"","frontmatter":{},"headers":[],"relativePath":"documentation/console-forwarding.md","filePath":"documentation/console-forwarding.md"}'),n={name:"documentation/console-forwarding.md"};function i(o,e,l,d,p,c){return r(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="console-forwarding" tabindex="-1">Console Forwarding <a class="header-anchor" href="#console-forwarding" aria-label="Permalink to “Console Forwarding”">​</a></h1><p>YggUtils provides a transparent console interface — anything you type is sent directly to the running server, and everything the server outputs is printed back to you.</p><h2 id="input-forwarding" tabindex="-1">Input Forwarding <a class="header-anchor" href="#input-forwarding" aria-label="Permalink to “Input Forwarding”">​</a></h2><p>A dedicated background thread reads lines from your terminal&#39;s stdin and writes them to the server process&#39;s stdin. This means all standard server commands work as expected:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>say Hello, world!</span></span>
<span class="line"><span>op PlayerName</span></span>
<span class="line"><span>whitelist add PlayerName</span></span>
<span class="line"><span>stop</span></span></code></pre></div><p>Input is forwarded after you press Enter. Empty lines are ignored.</p><h2 id="output-streaming" tabindex="-1">Output Streaming <a class="header-anchor" href="#output-streaming" aria-label="Permalink to “Output Streaming”">​</a></h2><p>The server&#39;s stdout and stderr are merged into a single stream. YggUtils reads this stream line by line and:</p><ul><li>Prints each line to your console immediately</li><li>Appends each line to <code>YggUtils-server.log</code> in the working directory</li></ul><p>There is no prefix or wrapper label added to server output — what the server prints is exactly what you see.</p><h2 id="log-file" tabindex="-1">Log File <a class="header-anchor" href="#log-file" aria-label="Permalink to “Log File”">​</a></h2><p>All server output is appended to <code>YggUtils-server.log</code>. The file grows across restarts, giving you a continuous history of the server&#39;s output.</p><p>If you want per-session logs, clear or rotate this file manually before starting the server.</p><h2 id="limitations" tabindex="-1">Limitations <a class="header-anchor" href="#limitations" aria-label="Permalink to “Limitations”">​</a></h2><p>YggUtils does not intercept or parse server output. It has no awareness of server events, player activity, or log levels. If you need structured log handling, RCON integration, or remote console access, those should be managed at the Minecraft server or plugin level.</p>`,15)])])}const u=a(n,[["render",i]]);export{g as __pageData,u as default};
